 		cancel_delayed_work_sync(&adapter->serv_task);
 		cancel_delayed_work_sync(&adapter->mbx_task);
 	}
 	idpf_ptp_release(adapter);

 	clear_bit(IDPF_HR_RESET_IN_PROG, adapter->flags);
 }



